INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('lesson:LATEST-029','lesson','Windows / odzyskiwanie','Windows Recovery — naprawa obrazu i reinstalacja bez utraty danych','Windows Recovery — naprawa obrazu i reinstalacja bez utraty danych','steps: Zapisz objaw i kod błędu; sprawdź, czy sprzętowy nośnik jest zdrowy.; Zabezpiecz dane na osobnym nośniku i sprawdź odczyt kopii.; Potwierdź klucz odzyskiwania BitLocker.; Wybierz Startup Repair, System Restore, naprawę obrazu lub reinstalację zgodnie z diagnozą.; Wyjaśnij klientowi wpływ wybranej opcji na dane i aplikacje.; Po naprawie zainstaluj sterowniki OEM i wykonaj testy urządzeń. body: Naprawa systemu, odzyskiwanie obrazu, reset i czysta instalacja mają różny wpływ na pliki i aplikacje. Najpierw rozpoznaj problem, zabezpiecz dane oraz potwierdź klucz BitLocker. warning: Nie wykonuj resetu lub czystej instalacji jako pierwszego kroku przy niezabezpieczonych danych. WinRE nie zastępuje kopii zapasowej. source: Microsoft Windows Recovery Environment','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','WinRE,Reset this PC,Recovery,Windows setup','Microsoft Windows Recovery Environment'),
('lesson:LATEST-030','lesson','Grafika / AMD Radeon','AMD Adrenalin 26.10.1 — kontrola daty i zgodności sterownika','AMD Adrenalin 26.10.1 — kontrola daty i zgodności sterownika','steps: Odczytaj GPU, wersję Windows i numer obecnego sterownika.; Sprawdź, czy urządzenie jest laptopem/AIO z pakietem OEM.; Porównaj datę i numer sterownika z oficjalną stroną AMD.; Utwórz punkt przywracania, jeśli system i procedura to wspierają.; Zainstaluj wyłącznie właściwy pakiet, po czym uruchom ponownie system.; Testuj wyświetlanie, audio HDMI/DP, akcelerację, uśpienie i błędy sterownika. body: AMD opublikował Adrenalin 26.10.1 WHQL 20 października 2026. Dla laptopów i komputerów AIO AMD zaleca sterowniki OEM, gdy są dostosowane do systemowych funkcji. W serwisie numer wersji i model GPU trzeba porównać z oficjalnym wpisem. warning: Nie aktualizuj sterownika tylko dlatego, że numer jest wyższy. Na laptopach pakiet OEM może być właściwszy niż uniwersalny. source: AMD Ryzen 9 9900X official downloads','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','AMD,Radeon,Adrenalin,26.10.1,WHQL','AMD Ryzen 9 9900X official downloads'),
('lesson:LATEST-031','lesson','Pamięć / test RAM','MemTest86+ — ocena błędów pamięci DDR4/DDR5','MemTest86+ — ocena błędów pamięci DDR4/DDR5','steps: Zapisz konfigurację RAM, sloty, timing, profil i BIOS.; Wyłącz niestabilne OC/XMP/EXPO do testu bazowego.; Uruchom aktualne narzędzie testowe z oficjalnego źródła.; Zapisz numer testu i adresy błędów.; Wykonuj próby pojedynczych modułów i slotów według instrukcji płyty.; Po zmianie konfiguracji uruchom test ponownie i opisz warunki. body: Test pamięci należy uruchamiać w kontrolowanej konfiguracji i zapisywać model, ustawienia, liczbę przebiegów oraz błędy. Błąd testu nie zawsze oznacza uszkodzony moduł; przyczyna może dotyczyć slotu, kontrolera lub ustawień. warning: Nie testuj pamięci przy niestabilnym zasilaniu ani z ustawieniami przekraczającymi specyfikację, jeżeli celem jest ocena gwarancyjna. source: MemTest86+ official project','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','MemTest86+,DDR4,DDR5,RAM,stability','MemTest86+ official project'),
('lesson:LATEST-032','lesson','Grafika / zasilanie GPU','Zasilanie GPU 12V-2x6 — kontrola przewodu i złącza','Zasilanie GPU 12V-2x6 — kontrola przewodu i złącza','steps: Wyłącz komputer i odłącz zasilanie przed oględzinami złącza.; Oceń, czy wtyk i gniazdo mają przebarwienia, stopienie lub odkształcenia.; Sprawdź, czy przewód jest przewodem właściwym dla danego modelu zasilacza.; Zweryfikuj pełne osadzenie złącza i zalecany dystans gięcia według OEM.; Po wymianie uszkodzonego przewodu wykonaj kontrolowany test pod obciążeniem.; Monitoruj temperaturę, stabilność i brak zapachu/odgłosów. body: Nowoczesne karty graficzne mogą używać złączy wysokoprądowych 12V-2x6 lub zgodnych przewodów OEM. Krytyczne jest pełne osadzenie wtyku, prawidłowy promień gięcia i użycie przewodu dopuszczonego przez producenta zasilacza. warning: Nie używaj uszkodzonego, nadtopionego ani niepewnego przewodu. Nie mieszaj modularnych przewodów od różnych modeli zasilaczy. source: NVIDIA GeForce RTX 50 and PSU OEM guidance','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','12V-2x6,GPU,power cable,PCIe','NVIDIA GeForce RTX 50 and PSU OEM guidance'),
('lesson:LATEST-033','lesson','Sieć / router','Router Wi-Fi 7 — firmware, WPA3 i diagnostyka kanałów','Router Wi-Fi 7 — firmware, WPA3 i diagnostyka kanałów','steps: Zapisz model routera, rewizję sprzętową i wersję firmware.; Sprawdź oficjalne aktualizacje producenta i biuletyny bezpieczeństwa.; Zbierz konfigurację pasm, kanałów i zabezpieczeń bez ujawniania hasła.; Przetestuj połączenie lokalne w pobliżu routera, a potem w kilku punktach.; Sprawdź logi, zakłócenia i zgodność adaptera klienckiego.; Po aktualizacji firmware zweryfikuj wszystkie SSID, urządzenia i sieć gościnną. body: Wysoka szybkość Wi-Fi 7 nie wynika tylko z adaptera. Router, szerokość kanału, pasmo 6 GHz, region, firmware, zabezpieczenia i rozmieszczenie anten wpływają na łączność. warning: Nie resetuj routera bez zapisania konfiguracji i zgody właściciela. Nie publikuj haseł Wi-Fi, kluczy ani publicznego IP klienta. source: Wi-Fi 7 Intel specifications and router OEM support','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','router,Wi-Fi 7,WPA3,firmware,6GHz','Wi-Fi 7 Intel specifications and router OEM support'),
('lesson:LATEST-034','lesson','Bateria / Li-ion','Laptop z baterią Li-ion — diagnostyka zużycia i bezpieczeństwo','Laptop z baterią Li-ion — diagnostyka zużycia i bezpieczeństwo','steps: Oceń wizualnie obudowę i touchpad, czy nie są wypychane przez baterię.; Jeśli bateria jest spuchnięta, przerwij ładowanie i nie naciskaj jej.; Odczytaj raport baterii i parametry diagnostyczne OEM.; Sprawdź zgodność zasilacza i zachowanie ładowania na zatwierdzonym adapterze.; Dobierz część wyłącznie po numerze OEM i rewizji.; Po wymianie sprawdź ładowanie, rozładowanie, temperaturę i raport systemu. body: Baterie litowo-jonowe mają ograniczoną żywotność i mogą ulec spuchnięciu, przegrzaniu lub uszkodzeniu mechanicznemu. Zmiana pojemności projektowej i pełnej pojemności wymaga interpretacji względem cykli i temperatur. warning: Nie przebijaj, nie zgniataj ani nie odkształcaj ogniw. Uszkodzona/spuchnięta bateria wymaga procedury producenta i bezpiecznej utylizacji. source: OEM lithium-ion battery service guidance','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','battery,Li-ion,health,swelling,charging','OEM lithium-ion battery service guidance'),
('lesson:LATEST-035','lesson','Obraz / laptop eDP','Laptop — diagnostyka taśmy eDP i czarnego obrazu','Laptop — diagnostyka taśmy eDP i czarnego obrazu','steps: Sprawdź jasność, skrót wyświetlania i wybrane wyjście obrazu.; Podłącz znany sprawny monitor i porównaj obraz.; Przetestuj latarką obraz przy podejrzeniu braku podświetlenia.; Odłącz baterię i zasilacz zgodnie z instrukcją OEM przed pracą wewnątrz.; Sprawdź złącze eDP, zatrzask i prowadzenie taśmy bez ciągnięcia za przewody.; Po złożeniu sprawdź obraz, jasność, zamykanie pokrywy i uśpienie. body: Czarny ekran może wynikać z matrycy, podświetlenia, taśmy eDP, złącza, czujnika pokrywy, GPU lub firmware. Wymiana matrycy bez testu na monitorze zewnętrznym i diagnozy zasilania jest ryzykowna. warning: Nie podłączaj ani nie odłączaj taśmy matrycy przy zasilaniu. Nie używaj metalowego narzędzia przy złączu eDP. source: OEM laptop display service manuals','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','eDP,matryca,laptop,black screen,display cable','OEM laptop display service manuals'),
('lesson:LATEST-036','lesson','Płyta główna / POST','Diagnostyka płyty głównej bez POST — sekwencja i logi','Diagnostyka płyty głównej bez POST — sekwencja i logi','steps: Zapisz model płyty, rewizję i kod POST/diody.; Sprawdź zewnętrzne zasilanie oraz prawidłowe podłączenie 24-pin/EPS.; Odłącz urządzenia zewnętrzne i wykonaj minimalną konfigurację według manuala.; Przetestuj pojedynczy moduł RAM w zalecanym slocie.; Sprawdź GPU/wyjście wideo i diagnostykę monitora niezależnie.; Interpretuj kody według dokumentacji modelu; nie zwieraj przypadkowych pinów. body: Brak POST wymaga rozdzielenia zasilania standby, reakcji EC, inicjalizacji RAM/CPU i wyjścia obrazu. Kody LED i Q-Code są specyficzne dla płyty i jej instrukcji. warning: Nie uruchamiaj płyty po zalaniu lub z widocznym zwarciem. Nie podmieniaj CPU/BIOS, dopóki nie zawęzisz przyczyny. source: Motherboard OEM user and service manuals','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','POST,Q-Code,DRAM,CPU,UEFI,motherboard','Motherboard OEM user and service manuals'),
('lesson:LATEST-037','lesson','Firmware / UEFI','Diagnostyka po aktualizacji firmware — UEFI capsule i rollback','Diagnostyka po aktualizacji firmware — UEFI capsule i rollback','steps: Zapisz wersję firmware i źródło aktualizacji.; Sprawdź, czy plik jest przeznaczony do dokładnego modelu i rewizji.; Zweryfikuj podpis i sumę kontrolną, jeśli producent je udostępnia.; Zabezpiecz dane, klucz BitLocker i stabilne zasilanie.; Postępuj wyłącznie zgodnie z procedurą OEM; nie przerywaj aktualizacji.; Po restarcie sprawdź wersję, Secure Boot, TPM i urządzenia. body: Aktualizacja firmware może być dostarczona przez narzędzie OEM, Windows Update lub mechanizm UEFI capsule. Właściwa procedura zależy od modelu, regionu, rewizji i sposobu podpisania obrazu. warning: Nie wykonuj downgrade BIOS bez wyraźnej procedury OEM. Nie używaj firmware z nieoficjalnych mirrorów. source: OEM firmware and Secure Boot documentation','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','UEFI capsule,firmware,BIOS,rollback,OEM','OEM firmware and Secure Boot documentation'),
('lesson:LATEST-038','lesson','Windows / diagnostyka sprzętu','Windows 11 — logi WHEA i błędy sprzętowe PCIe','Windows 11 — logi WHEA i błędy sprzętowe PCIe','steps: Zapisz pełny identyfikator zdarzenia i XML wpisu.; Sprawdź datę, źródło błędu, APIC ID lub segment/bus/device/function jeśli występują.; Porównaj z historią BIOS, sterowników, OC i urządzeń PCIe.; Przywróć ustawienia fabryczne i testuj pojedynczy element.; Oceń błędy pod obciążeniem i w spoczynku.; Dokumentuj korelację, nie przypisuj winy części bez potwierdzenia testem. body: WHEA rejestruje raporty błędów sprzętowych, ale sama nazwa zdarzenia nie wskazuje automatycznie uszkodzonego CPU czy GPU. Ważne są numer źródła błędu, komponent, adres i powtarzalność. warning: Nie wymieniaj CPU ani płyty wyłącznie na podstawie jednego WHEA-Logger. Odczyty interpretuj z dokumentacją Microsoft i OEM. source: Microsoft Windows hardware error architecture','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','WHEA,Event Viewer,PCIe,hardware errors','Microsoft Windows hardware error architecture'),
('lesson:LATEST-039','lesson','Grafika / test GPU','Testowanie GPU — VRAM, hotspot, artefakty i TDR','Testowanie GPU — VRAM, hotspot, artefakty i TDR','steps: Zapisz model GPU, VBIOS, sterownik i konfigurację zasilania.; Zapisz temperaturę GPU, hotspot, VRAM i wentylatory w spoczynku.; Sprawdź obraz w BIOS i na pulpicie, a także innym kablu/monitorze.; Uruchom krótki test VRAM i obciążenie 3D dopiero po potwierdzeniu chłodzenia.; Zapisz błędy, artefakty, reset sterownika i moment wystąpienia.; Po naprawie powtórz test w identycznych warunkach oraz sprawdź kilka aplikacji. body: Diagnostyka GPU powinna odróżnić problemy temperatury, zasilania, VRAM, sterownika, kabla/monitora i samej aplikacji. FPS bez kontroli warunków nie jest testem jakościowym. warning: Przerwij test przy artefaktach, resetach, zapachu lub gwałtownym wzroście temperatury. Nie flashuj VBIOS bez oficjalnej procedury i zgodności. source: NVIDIA RTX 50 and GPU vendor diagnostics','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','GPU,VRAM,hotspot,TDR,artifact,benchmark','NVIDIA RTX 50 and GPU vendor diagnostics'),
('lesson:LATEST-040','lesson','Windows / ARM64','Laptop z procesorem ARM — diagnostyka sterowników i zgodności','Laptop z procesorem ARM — diagnostyka sterowników i zgodności','steps: Zapisz model SoC, architekturę systemu i wersję Windows.; Sprawdź dostępność sterownika ARM64 na stronie OEM.; Zweryfikuj, czy aplikacja działa natywnie czy przez emulację.; Testuj urządzenia USB, audio, kamerę i dock z pakietem OEM.; Nie instaluj sterowników x64 na ARM64.; W raporcie rozdziel problem aplikacji od problemu urządzenia/sterownika. body: Urządzenia Windows na ARM64 mają odmienną zgodność sterowników i aplikacji od platform x64. W serwisie trzeba identyfikować architekturę systemu oraz sterowniki przeznaczone dla konkretnego urządzenia. warning: Nie stosuj pakietów sterowników x64 tylko dlatego, że nazwa modelu jest podobna. Nie wymuszaj niepodpisanych sterowników. source: Microsoft Windows on Arm developer and support docs','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','ARM64,Windows,drivers,compatibility','Microsoft Windows on Arm developer and support docs'),
('lesson:LATEST-041','lesson','Zasilanie / USB-C','Diagnostyka zasilania USB-C i ładowania laptopa','Diagnostyka zasilania USB-C i ładowania laptopa','steps: Sprawdź wymagania mocy z etykiety i dokumentacji OEM.; Użyj właściwego portu z funkcją ładowania.; Porównaj z oryginalnym zasilaczem i certyfikowanym kablem o odpowiednim ratingu.; Zapisz komunikat BIOS/Windows o zasilaczu lub mocy.; Sprawdź zachowanie w spoczynku i pod obciążeniem.; Oceń gniazdo, port i kontroler tylko według procedury OEM. body: Ładowanie USB-C wymaga negocjacji Power Delivery, odpowiedniej mocy ładowarki, kabla, portu i polityki platformy. Niski poziom mocy może powodować komunikat o wolnym ładowaniu lub rozładowanie pod obciążeniem. warning: Nie zwieraj pinów złącza USB-C i nie mierz nieznanych linii bez odpowiedniego adaptera diagnostycznego. source: USB-IF USB-C and power delivery documentation','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','USB-C,Power Delivery,charging,adapter','USB-IF USB-C and power delivery documentation'),
('lesson:LATEST-042','lesson','Dyski / awaria mechaniczna','Diagnostyka dysku po upadku — HDD i SSD','Diagnostyka dysku po upadku — HDD i SSD','steps: Zapytaj o dokładny przebieg upadku i czy dysk był zasilony.; Jeśli HDD klika, stuka lub nie rozpędza się, przerwij kolejne próby.; Zidentyfikuj dysk bez zapisu na nim, jeśli jest to bezpieczne.; Przy ważnych danych skieruj nośnik do laboratorium odzyskiwania danych.; Jeżeli nośnik jest stabilny, wykonaj kopię sektorową na inny dysk zgodnie z procedurą.; Weryfikuj integralność kopii i nie naprawiaj oryginału przed odzyskaniem danych. body: Po upadku HDD może mieć uszkodzenia mechaniczne; ponowne uruchamianie i skanowanie może pogorszyć stan. SSD także może ulec uszkodzeniu złącza, PCB lub kontrolera. Priorytetem jest ocena ryzyka i ochrona danych. warning: Nie uruchamiaj CHKDSK /F ani testów powierzchni na mechanicznie uszkodzonym HDD z ważnymi danymi. source: Professional data recovery best practices','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','HDD,SSD,drop,mechanical failure,data recovery','Professional data recovery best practices'),
('lesson:LATEST-043','lesson','Porty / USB','Diagnostyka portu USB — USB 2.0/3.x/USB4 i zasilanie','Diagnostyka portu USB — USB 2.0/3.x/USB4 i zasilanie','steps: Zapisz typ portu, urządzenia i kabla.; Przetestuj urządzenie bezpośrednio w komputerze, bez huba.; Porównaj z innym portem i kablem o znanych parametrach.; Sprawdź identyfikator urządzenia i logi kontrolera USB.; Zweryfikuj wymaganą funkcję: dane, obraz, ładowanie lub Thunderbolt.; Po aktualizacji sterownika/chipsetu sprawdź uśpienie i wybudzanie. body: USB-C oraz USB-A mogą obsługiwać różne protokoły, szybkości, zasilanie i role. Problem z urządzeniem może wynikać z kabla, huba, kontrolera, sterownika, zasilania albo wymaganego trybu alternatywnego. warning: Nie zakładaj, że port o tym samym kształcie ma tę samą szybkość, moc lub tryb obrazu. Unikaj nieznanych adapterów. source: USB-IF USB4 specifications','stepsEn: Step 1: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 2: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 3: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 4: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 5: verify the exact model, document the baseline, perform one controlled test, and record the result.; Step 6: verify the exact model, document the baseline, perform one controlled test, and record the result. bodyEn: Current, model-specific service guide. Verify the exact platform, hardware revision, firmware and OEM documentation before performing changes. warningEn: Follow the exact OEM service procedure. Back up user data and stop when electrical, battery or data-recovery safety limits are reached.','USB,USB-C,USB4,USB 3,hub,Power','USB-IF USB4 specifications'),
('lesson:GLOBAL-071','lesson','Zasilanie PC','Diagnostyka zasilacza ATX bez otwierania obudowy','ATX power supply diagnostics without opening the PSU','steps: Zapisz model, moc znamionową i objaw; sprawdź, czy problem występuje także na innym sprawnym przewodzie zasilającym.; Odłącz komputer od sieci przed przepinaniem przewodów i obejrzyj złącza pod kątem nadpaleń lub luzu.; Wykonaj test zasilacza zgodnie z instrukcją producenta/testera; nie zwieraj przypadkowych pinów.; Jeśli wykonujesz pomiary, użyj odpowiedniego adaptera i porównaj wyniki z tolerancjami podanymi dla danego standardu/modelu.; Sprawdź zachowanie pod kontrolowanym obciążeniem i powtarzalność startu; zanotuj warunki testu. body: Zasilacz ATX dostarcza kilka linii zasilania, a jego sprawność zależy od obciążenia i sygnałów sterujących płyty. Wentylator, który się nie obraca, nie musi oznaczać awarii — wiele modeli ma tryb półpasywny. Najpierw sprawdź przewód, gniazdo, przełącznik i warunki gwarancji. Do pomiarów używaj wyłącznie bezpiecznych punktów po stronie niskiego napięcia i właściwych adapterów testowych. warning: Nigdy nie otwieraj zasilacza sieciowego. Wewnątrz mogą występować niebezpieczne napięcia także po odłączeniu. Przy zapachu spalenizny, iskrzeniu lub nadtopionym złączu przerwij test. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record the model, rated power and symptom; check whether the issue also occurs with a known-good power cable.; Disconnect AC power before changing cables and inspect connectors for heat damage or looseness.; Use a PSU tester according to its manual; do not short arbitrary pins.; If measuring, use a suitable breakout adapter and compare readings with the tolerances specified for the particular standard/model.; Check operation under controlled load and repeatability; record test conditions. bodyEn: An ATX PSU provides multiple power rails, and its operation depends on load and motherboard control signals. A fan that does not spin does not automatically indicate a fault; many units use a semi-passive mode. Start with the cable, outlet, switch and warranty conditions. Use only safe low-voltage test points and proper test adapters. warningEn: Never open a mains power supply. Dangerous voltages may remain inside after disconnection. Stop testing if there is a burning smell, arcing or a melted connector.','ATX,PSU,12V,5V,3.3V,standby','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-072','lesson','Zasilanie laptopów','Sekwencja startowa laptopa: adapter, ładowanie, EC i POST','Laptop startup sequence: adapter, charging, EC and POST','steps: Zidentyfikuj pełny model laptopa, oznaczenie płyty i rewizję PCB.; Sprawdź oryginalny lub zgodny adapter: napięcie, moc, złącze i identyfikację.; Zapisz reakcję diod, przycisku Power, wentylatora i poboru prądu bez wielokrotnego wymuszania startu.; Porównaj kolejność sygnałów i szyn zasilania ze schematem/boardview właściwej płyty.; Wykonuj pomiary tylko w granicach procedury serwisowej; przerwij przy nieznanym zwarciu lub przegrzewaniu. body: Brak startu laptopa należy rozdzielić na wejście zasilania, rozpoznanie adaptera, ładowanie baterii, napięcia czuwania, reakcję kontrolera EC i etap POST. Samo świecenie diody ładowania nie potwierdza prawidłowej pracy całej płyty. Każdy punkt pomiarowy i kolejność sygnałów muszą pochodzić ze schematu dokładnej rewizji. warning: Nie zgaduj napięć ani pinów na podstawie podobnego modelu. Nie podawaj napięcia z zasilacza laboratoryjnego na nieznane piny. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Identify the exact laptop model, board number and PCB revision.; Check the original or compatible adapter: voltage, wattage, connector and identification.; Record LED, power-button, fan and current-draw behaviour without repeatedly forcing startup.; Compare signal and power-rail sequence with the schematic/boardview for that exact board.; Measure only within the service procedure; stop for an unidentified short or overheating. bodyEn: A laptop no-start condition should be separated into input power, adapter identification, battery charging, standby rails, EC response and POST. A charging LED alone does not prove the whole board is operating correctly. Every measurement point and signal sequence must come from the schematic for the exact board revision. warningEn: Do not guess voltages or pins from a similar model. Never inject bench-supply voltage into unknown pins.','laptop,EC,KBC,charger,POST,standby','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-073','lesson','USB-C i zasilanie','USB-C Power Delivery: diagnoza ładowania laptopa','USB-C Power Delivery: laptop charging diagnosis','steps: Sprawdź specyfikację laptopa: wymagane profile napięcia/mocy i porty obsługujące ładowanie.; Użyj znanego sprawnego adaptera oraz certyfikowanego przewodu o odpowiedniej klasie mocy.; Sprawdź, czy port USB-C nie jest mechanicznie uszkodzony, zabrudzony lub poluzowany.; Porównaj wyniki z miernikiem/testerem USB-C PD przeznaczonym do danego zakresu; nie wkładaj sond w port.; Zweryfikuj ładowanie w stanie wyłączonym i pod obciążeniem oraz zapisz negocjowany profil. body: USB-C jest typem złącza, a nie gwarancją konkretnej mocy. Ładowanie zależy od negocjacji USB Power Delivery, możliwości adaptera, przewodu, kontrolera portu i wymagań laptopa. Przewód może obsługiwać ładowanie o ograniczonej mocy lub transmisję danych, ale nie każdy zestaw zapewnia wymagany profil PD. warning: Przerwij przy przegrzewaniu, zapachu spalenizny, iskrzeniu lub luźnym/nadtopionym porcie. Nie wymuszaj nieobsługiwanego profilu zasilania. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Check the laptop specification for required voltage/power profiles and charging-capable ports.; Use a known-good adapter and a certified cable rated for the required power.; Inspect the USB-C port for mechanical damage, debris or looseness.; Use a USB-C PD meter/tester designed for the relevant range; never insert bare probes into the port.; Verify charging while powered off and under load, and record the negotiated profile. bodyEn: USB-C describes a connector, not a guaranteed power level. Charging depends on USB Power Delivery negotiation, adapter capability, cable, port controller and laptop requirements. A cable may support limited charging or data, but not every combination provides the required PD profile. warningEn: Stop for overheating, burning smell, arcing or a loose/melted port. Never force an unsupported power profile.','USB-C,PD,CC,e-marker,charger','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-074','lesson','Baterie i bezpieczeństwo','Diagnostyka baterii laptopa i ocena jej zużycia','Laptop battery diagnostics and wear assessment','steps: Odczytaj raport baterii z narzędzia systemowego lub diagnostyki producenta.; Porównaj pojemność projektową z pojemnością pełnego ładowania i zanotuj liczbę cykli.; Sprawdź temperaturę, stabilność ładowania i nagłe spadki poziomu w kontrolowanym teście.; Obejrzyj obudowę baterii bez naciskania i wyginania pakietu.; Przy degradacji zaproponuj zgodny zamiennik o właściwym numerze części i wykonaj test po wymianie. body: Bateria litowo-jonowa jest elementem eksploatacyjnym z własnym układem BMS. Pojemność projektowa, pojemność pełnego ładowania, liczba cykli i temperatura pomagają ocenić stan, ale sam raport programowy nie zastępuje inspekcji fizycznej. Spuchnięcie, zapach lub uszkodzenie obudowy to sygnał do natychmiastowego przerwania pracy. warning: Nie przebijaj, nie ściskaj, nie rozbieraj i nie ładuj uszkodzonego lub spuchniętego pakietu. Postępuj według lokalnych zasad transportu i utylizacji baterii. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Read the battery report using the operating system or manufacturer diagnostics.; Compare design capacity with full-charge capacity and record the cycle count.; Check temperature, charging stability and sudden percentage drops under a controlled test.; Inspect the battery enclosure without pressing or bending the pack.; For degradation, source a compatible replacement with the correct part number and test after replacement. bodyEn: A lithium-ion battery is a consumable component with its own BMS. Design capacity, full-charge capacity, cycle count and temperature help assess condition, but a software report does not replace physical inspection. Swelling, odour or enclosure damage requires immediate work stoppage. warningEn: Do not puncture, compress, disassemble or charge a damaged or swollen pack. Follow local battery transport and disposal rules.','battery,health,cycle count,charging','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-075','lesson','Pamięć RAM','RAM: testowanie modułów, slotów i profili XMP/EXPO','RAM: testing modules, slots and XMP/EXPO profiles','steps: Zapisz model płyty, CPU, wersję BIOS i dokładne oznaczenie zestawu RAM.; Przy wyłączonym zasilaniu sprawdź poprawne osadzenie modułów i instrukcję obsady slotów.; Przywróć ustawienia domyślne JEDEC i wykonaj pełny test pamięci poza systemem operacyjnym.; Testuj pojedynczy moduł w zalecanym slocie, a następnie moduły i sloty osobno.; Włącz XMP/EXPO dopiero po stabilnym teście bazowym; po zmianie ponów długi test i obciążenie mieszane. body: Błędy pamięci mogą wynikać z modułu, slotu, kontrolera pamięci CPU, ustawień timingów, napięcia, BIOS-u lub niezgodności zestawu. Weryfikację prowadź od ustawień JEDEC i konfiguracji minimalnej, zanim włączysz profil podkręcania XMP/EXPO. warning: Przed wyjmowaniem RAM odłącz zasilanie. Nie zwiększaj napięcia pamięci w celu ukrycia błędów bez znajomości specyfikacji CPU, płyty i modułów. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record the motherboard, CPU, BIOS version and exact memory kit part number.; With power disconnected, check DIMM seating and the recommended slot population order.; Restore JEDEC defaults and run a full memory test outside the operating system.; Test one module in the recommended slot, then test modules and slots separately.; Enable XMP/EXPO only after a stable baseline; repeat extended memory and mixed-load testing after the change. bodyEn: Memory errors may be caused by a DIMM, slot, CPU memory controller, timings, voltage, BIOS or kit incompatibility. Start with JEDEC defaults and a minimal configuration before enabling an XMP/EXPO overclocking profile. warningEn: Disconnect power before removing memory. Do not raise memory voltage to mask errors without understanding CPU, motherboard and DIMM specifications.','RAM,DDR4,DDR5,XMP,EXPO,MemTest','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-076','lesson','Dyski i dane','SSD NVMe i SATA: SMART, temperatura i diagnostyka','NVMe and SATA SSD: SMART, temperature and diagnostics','steps: Zapisz dokładny model, firmware, interfejs i pojemność nośnika.; Odczytaj SMART/NVMe log w narzędziu producenta lub wiarygodnym czytniku; zachowaj raport.; Sprawdź temperaturę, liczbę błędów, ostrzeżenia i stabilność wykrywania po zimnym starcie.; Gdy pojawiają się błędy lub znikanie dysku, najpierw wykonaj kopię lub obraz sektorowy na sprawny nośnik.; Po wymianie sprawdź firmware, system plików, TRIM i test odczytu/zapisu bez obciążania starego nośnika. body: Nośnik może zgłaszać ostrzeżenia SMART, błędy nośnika, wysoką temperaturę, utratę łącza lub spadek wydajności. Atrybuty i interpretacja logów zależą od producenta oraz interfejsu. Przed naprawą systemu plików lub aktualizacją firmware zabezpiecz dane, szczególnie gdy nośnik znika lub zwalnia. warning: Przy krytycznych danych, odgłosach mechanicznych HDD lub niestabilnym nośniku nie uruchamiaj wielokrotnych testów obciążeniowych. Rozważ profesjonalny odzysk. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record the exact drive model, firmware, interface and capacity.; Read SMART/NVMe logs with the vendor utility or a reputable reader; save the report.; Check temperature, error counters, warnings and detection stability after a cold boot.; If errors or disconnects occur, make a backup or sector image to a healthy drive first.; After replacement, verify firmware, filesystem, TRIM and read/write behaviour without stressing the failing drive. bodyEn: A drive may report SMART warnings, media errors, high temperature, link loss or performance degradation. Attributes and log interpretation vary by manufacturer and interface. Back up data before filesystem repair or firmware updates, especially when a drive disconnects or slows down. warningEn: For critical data, mechanical HDD noises or an unstable drive, avoid repeated stress tests. Consider professional data recovery.','SSD,NVMe,SATA,SMART,health','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-077','lesson','Odzysk danych','Bezpieczne obrazowanie i klonowanie dysku przed naprawą','Safe disk imaging and cloning before repair','steps: Ustal priorytet: dane klienta, szybka kopia plików czy obraz całego nośnika.; Zapisz identyfikatory i pojemności źródła oraz celu; cel musi być co najmniej tak duży, jeśli tworzysz klon 1:1.; Nie zapisuj na źródłowym nośniku; w razie możliwości użyj blokady zapisu.; Użyj narzędzia obsługującego mapę błędów i możliwość wznowienia; zapisuj log postępu.; Weryfikuj obraz na kopii, nigdy na jedynym oryginale, i dokumentuj nieodczytane obszary. body: Obrazowanie sektorowe pozwala zabezpieczyć stan źródłowego nośnika przed naprawą systemu plików, migracją lub analizą. Klonowanie zwykłe i obrazowanie uszkodzonego dysku to różne zadania. Wybierz narzędzie z obsługą błędów odczytu i logiem, a źródło traktuj jako tylko do odczytu, gdy to możliwe. warning: Nie wykonuj CHKDSK, formatowania ani naprawy partycji na jedynej kopii danych z niestabilnego dysku. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Determine the priority: customer files, a quick file backup or a full-device image.; Record source and destination IDs and capacities; a 1:1 clone requires a destination at least as large.; Do not write to the source; use a write blocker where possible.; Use imaging software with an error map and resume support; keep a progress log.; Verify the image on a copy, never on the only original, and document unreadable regions. bodyEn: Sector imaging preserves the source drive before filesystem repair, migration or analysis. A normal clone and imaging a failing drive are different tasks. Choose a tool with read-error handling and logging, and keep the source read-only where possible. warningEn: Do not run CHKDSK, formatting or partition repair on the only copy of data from an unstable drive.','disk imaging,clone,backup,forensic','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-078','lesson','Windows i rozruch','Windows: naprawa rozruchu UEFI i analiza BCD','Windows: UEFI boot repair and BCD analysis','steps: Zapisz komunikat błędu, konfigurację UEFI i kolejność urządzeń startowych.; Sprawdź, czy dysk jest widoczny w firmware oraz czy system był instalowany w trybie UEFI/GPT.; Ustal status szyfrowania i upewnij się, że właściciel ma poprawny klucz odzyskiwania BitLocker.; Uruchom WinRE i odczytaj partycje oraz logi; wykonaj kopię danych, zanim zmienisz BCD/EFI.; Po naprawie wykonaj kilka zimnych startów i sprawdź, czy szyfrowanie oraz aktualizacje działają prawidłowo. body: Problemy rozruchu mogą wynikać z kolejności bootowania, partycji EFI, wpisów BCD, trybu UEFI/Legacy, uszkodzonego systemu plików albo zmian firmware. Przed zmianami sprawdź stan dysku oraz BitLocker. Polecenia naprawcze dobieraj do wykrytej instalacji i trybu bootowania. warning: Nie formatuj partycji EFI i nie usuwaj wpisów BCD bez kopii oraz rozpoznania układu dysku. Nie obchodź szyfrowania. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record the error, UEFI configuration and boot-device order.; Check whether firmware detects the drive and whether Windows was installed in UEFI/GPT mode.; Determine encryption status and ensure the owner has the correct BitLocker recovery key.; Boot WinRE and inspect partitions/logs; back up data before changing BCD/EFI.; After repair, perform several cold boots and verify encryption and updates work correctly. bodyEn: Boot failures may come from boot order, the EFI System Partition, BCD entries, UEFI/Legacy mode, filesystem damage or firmware changes. Check drive health and BitLocker before modifying anything. Choose repair commands based on the detected Windows installation and boot mode. warningEn: Do not format the EFI partition or remove BCD entries without a backup and verified disk layout. Do not bypass encryption.','Windows,UEFI,EFI,BCD,WinRE','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-079','lesson','Windows i bezpieczeństwo','BitLocker: diagnostyka żądania klucza odzyskiwania','BitLocker: diagnosing recovery-key prompts','steps: Zapisz identyfikator klucza wyświetlony na ekranie, ale nie zapisuj samego klucza w raporcie.; Ustal, czy wykonano aktualizację BIOS, zmianę płyty, TPM, Secure Boot lub kolejności rozruchu.; Właściciel powinien pobrać klucz z własnego konta Microsoft/organizacji lub dokumentacji IT.; Po prawidłowym odblokowaniu sprawdź stan ochrony i TPM; nie wyłączaj zabezpieczeń bez uzasadnienia.; Przed kolejną aktualizacją postępuj według procedury producenta i potwierdź dostęp do klucza. body: Żądanie klucza BitLocker po aktualizacji BIOS, zmianie TPM, Secure Boot, kolejności rozruchu lub płyty może być oczekiwanym mechanizmem ochrony, a nie awarią dysku. Należy potwierdzić właściciela i legalny dostęp do klucza, a następnie odtworzyć przyczynę zmiany pomiarów zaufania. warning: Nie próbuj omijać BitLocker ani pozyskiwać klucza bez zgody właściciela. Nie publikuj kluczy, identyfikatorów klienta ani danych konta. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record the recovery key ID shown on screen, but never place the recovery key itself in the report.; Determine whether BIOS, motherboard, TPM, Secure Boot or boot order changed.; The owner should retrieve the key from their own Microsoft/organization account or IT records.; After legitimate unlock, check protection and TPM state; do not disable security without justification.; Before another firmware update, follow the vendor procedure and confirm key availability. bodyEn: A BitLocker recovery prompt after BIOS updates, TPM/Secure Boot changes, boot-order changes or motherboard replacement may be an expected security response, not a drive failure. Verify ownership and legitimate access to the key, then identify which platform trust measurements changed. warningEn: Do not bypass BitLocker or obtain a key without the owner’s authorization. Never publish recovery keys, customer IDs or account data.','BitLocker,TPM,Secure Boot,recovery key','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-080','lesson','Firmware','BIOS/UEFI: przygotowanie bezpiecznej aktualizacji firmware','BIOS/UEFI: preparing a safe firmware update','steps: Sprawdź dokładny model, rewizję płyty, aktualną wersję i oficjalną stronę wsparcia.; Przeczytaj changelog, wymagane wersje pośrednie, ograniczenia i instrukcję odzyskiwania.; Zweryfikuj integralność pliku sumą kontrolną, jeśli producent ją publikuje.; Zabezpiecz dane i klucz BitLocker; w laptopie zapewnij stabilne zasilanie oraz sprawną baterię.; Aktualizuj wyłącznie metodą producenta; po aktualizacji sprawdź ustawienia UEFI, TPM, Secure Boot i rozruch. body: Aktualizacja BIOS/UEFI może poprawić zgodność lub bezpieczeństwo, ale błędny plik albo przerwane zasilanie może unieruchomić płytę. Plik musi pasować do pełnego modelu, rewizji i regionu urządzenia. Zanim rozpoczniesz, sprawdź informacje producenta o wymaganych wersjach pośrednich, ograniczeniach i metodzie odzyskiwania. warning: Nie aktualizuj firmware przy niestabilnym zasilaniu, błędach pamięci lub podejrzeniu awarii nośnika. Nie używaj obrazu z podobnego modelu. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Verify the exact model, board revision, current firmware and official support page.; Read the changelog, bridge-version requirements, limitations and recovery instructions.; Verify the file checksum when the vendor publishes one.; Back up data and the BitLocker recovery key; ensure stable power and a healthy battery on laptops.; Update only with the vendor method; afterwards verify UEFI, TPM, Secure Boot and boot settings. bodyEn: A BIOS/UEFI update may improve compatibility or security, but a wrong image or interrupted power can make the board unusable. The file must match the exact model, revision and region. Before starting, review the vendor notes for bridge versions, limitations and recovery methods. warningEn: Do not update firmware with unstable power, memory errors or a suspected drive failure. Never use an image from a merely similar model.','BIOS,UEFI,firmware,flash,rollback','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-081','lesson','Chłodzenie','Diagnostyka przegrzewania CPU i throttlingu','CPU overheating and throttling diagnosis','steps: Zapisz model CPU, chłodzenia, obudowy, temperaturę otoczenia i wersję BIOS.; Sprawdź logi temperatury, taktowania, poboru mocy i flag throttlingu w kontrolowanym obciążeniu.; Obejrzyj filtry, radiator, wentylatory i docisk chłodzenia; nie dotykaj pracujących elementów.; Jeśli demontujesz chłodzenie, oczyść powierzchnie i użyj pasty oraz momentu montażu zalecanych przez producenta.; Powtórz identyczny test i porównaj temperatury, zegary, hałas i stabilność. body: Wysoka temperatura może być skutkiem obciążenia, ograniczonego przepływu powietrza, złego montażu chłodzenia, krzywej wentylatora, zasilania lub nieprawidłowego odczytu czujnika. Temperatury graniczne zależą od konkretnego CPU. Analizuj trend, taktowanie, moc, temperaturę otoczenia i przyczynę ograniczenia wydajności. warning: Nie uruchamiaj testu obciążeniowego przy zatrzymanym wentylatorze, odłączonej pompie lub szybko rosnącej temperaturze. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record CPU, cooler, case, ambient temperature and BIOS version.; Log temperatures, clocks, power and throttling flags under a controlled workload.; Inspect filters, heatsink, fans and cooler mounting; keep hands away from moving parts.; If removing the cooler, clean contact surfaces and use vendor-recommended thermal compound and mounting pressure.; Repeat the same test and compare temperatures, clocks, noise and stability. bodyEn: High temperature may result from workload, restricted airflow, poor cooler mounting, fan curve, power delivery or sensor interpretation. Thermal limits depend on the exact CPU. Analyse trends, clock, power, ambient temperature and the reason for performance limiting. warningEn: Do not run stress tests with a stopped fan, disconnected pump or rapidly rising temperature.','CPU,temperature,throttling,thermal paste','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-082','lesson','Chłodzenie laptopów','Laptop: czyszczenie chłodzenia i wymiana materiału termicznego','Laptop: cleaning cooling and replacing thermal interface material','steps: Znajdź service manual i zanotuj długości śrub oraz kolejność demontażu.; Wyłącz laptop, odłącz adapter i wewnętrzną baterię zgodnie z instrukcją.; Unieruchom wirnik wentylatora przed usuwaniem kurzu i nie rozpędzaj go sprężonym powietrzem.; Zachowaj oryginalne rozmieszczenie i grubość padów; pastę nakładaj zgodnie z zaleceniami producenta.; Po montażu sprawdź obroty, temperatury, hałas i powtórz test obciążeniowy. body: Kurz w żeberkach radiatora może blokować wylot mimo widocznego obrotu wentylatora. Wymiana pasty lub padów wymaga zachowania ich grubości i rozmieszczenia; zbyt gruby pad może unieść radiator i pogorszyć kontakt CPU/GPU. Najpierw sprawdź instrukcję serwisową konkretnego modelu. warning: Nie używaj metalowych narzędzi do podważania baterii. Nie mieszaj padów termicznych o przypadkowej grubości. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Find the service manual and record screw lengths and disassembly order.; Power off the laptop, disconnect the adapter and internal battery according to the manual.; Hold the fan rotor while removing dust; do not overspin it with compressed air.; Preserve original thermal-pad placement and thickness; apply paste according to vendor guidance.; After assembly, check fan speed, temperatures, noise and repeat the load test. bodyEn: Dust packed into heatsink fins can block exhaust even when the fan visibly spins. Replacing paste or pads requires preserving their thickness and placement; an oversized pad may lift the heatsink and worsen CPU/GPU contact. Check the service manual for the exact model first. warningEn: Do not use metal tools to pry a battery. Do not substitute thermal pads with arbitrary thickness.','laptop,fan,heatsink,thermal pads','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-083','lesson','Grafika','GPU: artefakty obrazu, sterownik czy uszkodzenie sprzętu','GPU: visual artifacts, driver fault or hardware failure','steps: Zapisz model GPU, wersję sterownika, BIOS VBIOS, temperatury i warunki wystąpienia.; Sprawdź monitor i przewód na innym urządzeniu oraz inny port/kabel na badanym PC.; Przywróć ustawienia GPU do wartości domyślnych i wykonaj czystą instalację sterownika z oficjalnego źródła.; Testuj VRAM/GPU krótkimi, kontrolowanymi etapami, monitorując temperaturę i pobór mocy.; Porównaj zachowanie w innym systemie lub znanej sprawnej karcie, jeśli jest dostępna. body: Artefakty, migotanie, czarny ekran i reset sterownika mogą pochodzić z kabla, monitora, portu, sterownika, VRAM, GPU, temperatury lub zasilania. Nie diagnozuj uszkodzenia karty na podstawie jednego benchmarku. Zawęź problem, zmieniając pojedynczo tor sygnału i środowisko testowe. warning: Przerwij przy zapachu spalenizny, iskrzeniu, niestabilnym zasilaniu lub gwałtownym wzroście temperatury. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record GPU model, driver, VBIOS, temperatures and failure conditions.; Test the monitor and cable on another device and another port/cable on the affected PC.; Restore default GPU settings and clean-install the driver from the official source.; Test VRAM/GPU in short, controlled stages while monitoring temperature and power.; Compare behaviour in another OS or with a known-good GPU if available. bodyEn: Artifacts, flicker, black screens and driver resets may originate from the cable, monitor, port, driver, VRAM, GPU, temperature or power. Do not diagnose a failed card from one benchmark. Isolate the problem by changing one part of the signal path or test environment at a time. warningEn: Stop for a burning smell, arcing, unstable power or a rapid temperature rise.','GPU,artifacts,VRAM,driver,display','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-084','lesson','Monitory i obraz','Monitor: diagnostyka braku obrazu, migotania i złej rozdzielczości','Monitor: no signal, flicker and incorrect resolution','steps: Zapisz model monitora, rozdzielczość, odświeżanie i typ połączenia.; Sprawdź OSD monitora, źródło wejścia i komunikat diagnostyczny.; Użyj krótkiego, sprawnego kabla zgodnego z wymaganym standardem i pomiń adaptery.; Przetestuj monitor z innym źródłem oraz komputer z innym monitorem.; Zainstaluj właściwy sterownik GPU i wybierz tryb obsługiwany przez cały tor sygnału. body: Problem obrazu może wynikać z monitora, kabla, konwertera, GPU, EDID, częstotliwości odświeżania lub ustawień systemu. Test krzyżowy pozwala rozdzielić tor sygnału od urządzenia. Nie zakładaj, że każdy port, kabel i adapter obsłuży maksymalną rozdzielczość oraz odświeżanie monitora. warning: Nie rozbieraj monitora ani zasilacza monitora — wewnątrz mogą występować niebezpieczne napięcia. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record monitor model, resolution, refresh rate and connection type.; Check the monitor OSD, input source and diagnostic message.; Use a short, known-good cable for the required standard and remove adapters.; Test the monitor with another source and the PC with another monitor.; Install the correct GPU driver and choose a mode supported by the entire signal path. bodyEn: Display issues may come from the monitor, cable, adapter, GPU, EDID, refresh rate or OS settings. Cross-testing helps separate the signal path from the device. Do not assume every port, cable and adapter supports the monitor’s maximum resolution and refresh rate. warningEn: Do not open a monitor or its power supply; hazardous voltages may be present.','monitor,EDID,HDMI,DisplayPort,refresh rate','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-085','lesson','Sieć i łączność','Wi-Fi i Bluetooth: rozdzielenie problemu sterownika, anteny i routera','Wi-Fi and Bluetooth: isolating driver, antenna and router issues','steps: Zapisz model karty, wersję sterownika, pasmo, kanał i odległość od punktu dostępowego.; Sprawdź działanie na innej sieci oraz porównaj z innym urządzeniem w tej samej lokalizacji.; Zaktualizuj sterownik z oficjalnej strony producenta laptopa lub modułu.; Sprawdź mocowanie anten i przewodów tylko po bezpiecznym otwarciu zgodnie z manualem.; Przetestuj po wyłączeniu oszczędzania energii jako pojedynczej, odwracalnej zmiany. body: Zrywanie Wi-Fi może być związane z routerem, zakłóceniami, pasmem, antenami, kartą, sterownikiem lub ustawieniami oszczędzania energii. Bluetooth może korzystać z tego samego modułu i współdzielić pasmo 2,4 GHz. Testuj osobno różne sieci, pasma i urządzenia. warning: Nie demontuj anten przy włączonym urządzeniu. Nie skanuj sieci osób trzecich bez zgody. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record adapter model, driver, band, channel and distance to the access point.; Test another network and compare with another device in the same location.; Update the driver from the laptop or adapter manufacturer’s official support page.; Inspect antenna and cable connections only after safe disassembly according to the manual.; Test with power saving disabled as one reversible change. bodyEn: Wi-Fi drops may be caused by the router, interference, band, antennas, adapter, driver or power-saving settings. Bluetooth may share the same module and 2.4 GHz spectrum. Test different networks, bands and devices separately. warningEn: Do not disconnect antennas while the device is powered. Do not scan third-party networks without permission.','WiFi,Bluetooth,antenna,driver,router','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-086','lesson','Porty i interfejsy','Porty USB: brak wykrywania, zasilania lub niestabilne połączenie','USB ports: no detection, power or unstable connection','steps: Zidentyfikuj typ USB i wymagania zasilania/danych urządzenia.; Przetestuj znany sprawny przewód i urządzenie w porcie bezpośrednim, bez huba.; Sprawdź Menedżer urządzeń i zdarzenia USB; zanotuj kod błędu.; Obejrzyj port pod powiększeniem, szukając wygiętych styków i pękniętych mocowań.; Jeżeli port ma uszkodzenia, wyłącz urządzenie i zaplanuj naprawę zgodną z konstrukcją płyty. body: Port USB może nie działać z powodu przewodu, urządzenia, huba, zasilania portu, kontrolera, sterownika lub uszkodzenia mechanicznego. Zacznij od urządzenia i kabla, a następnie sprawdź porty bezpośrednie. Nie wkładaj metalowych przedmiotów do gniazda. warning: Nie mostkuj pinów zasilania i danych. Przy zwarciu lub nadmiernym nagrzewaniu portu odłącz zasilanie. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Identify the USB type and the peripheral’s power/data requirements.; Test a known-good cable and device on a direct port without a hub.; Inspect Device Manager and USB events; record any error code.; Inspect the port under magnification for bent contacts or cracked mounts.; If damaged, power down and plan a repair appropriate to the board construction. bodyEn: A USB port may fail due to the cable, peripheral, hub, port power, controller, driver or mechanical damage. Start with the device and cable, then test direct ports. Never insert metal objects into the connector. warningEn: Do not bridge power and data pins. Disconnect power if the port is shorted or overheating.','USB,USB-A,USB-C,hub,enumeration','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-087','lesson','Sieć przewodowa','Ethernet: diagnostyka linku, DHCP, DNS i prędkości','Ethernet: diagnosing link, DHCP, DNS and speed','steps: Sprawdź diody link/activity i stan karty sieciowej.; Podmień kabel i port switcha/routera na znane sprawne.; Odczytaj adres IP, maskę, bramę, DNS i szybkość linku.; Testuj osobno połączenie z bramą, rozwiązywanie DNS i dostęp do adresu zewnętrznego.; Po zmianie sterownika lub ustawień przywróć poprzednią konfigurację, jeśli test nie pomógł. body: Brak Internetu przez Ethernet nie oznacza automatycznie uszkodzonego portu. Sprawdź osobno link fizyczny, negocjację prędkości, adresację DHCP, bramę, DNS i trasę do Internetu. Używaj kabla i portu o potwierdzonej sprawności. warning: Nie zmieniaj ustawień routera produkcyjnego bez zgody administratora i kopii konfiguracji. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Check link/activity LEDs and adapter state.; Swap the cable and switch/router port for known-good ones.; Read the IP address, subnet mask, gateway, DNS and negotiated link speed.; Test gateway reachability, DNS resolution and access to an external address separately.; After driver or settings changes, revert the configuration if the test did not help. bodyEn: No Internet over Ethernet does not automatically mean a failed port. Check physical link, speed negotiation, DHCP addressing, gateway, DNS and Internet routing separately. Use a cable and port known to work. warningEn: Do not change a production router without administrator approval and a configuration backup.','Ethernet,LAN,DHCP,DNS,link','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-088','lesson','Windows i diagnostyka','Windows BSOD: analiza kodu zatrzymania i zrzutu pamięci','Windows BSOD: analysing stop codes and memory dumps','steps: Zapisz kod stop, czas awarii i zadanie wykonywane w chwili błędu.; Skopiuj minidump i raporty zdarzeń; usuń z nich dane osobowe przed udostępnieniem.; Sprawdź ostatnie aktualizacje sterowników i sprzętu, ale nie cofaj wielu zmian naraz.; Uruchom test RAM oraz sprawdź SMART dysku; obserwuj temperatury.; Weryfikuj hipotezę przez powtórzenie scenariusza po pojedynczej kontrolowanej zmianie. body: Ekran BSOD jest skutkiem krytycznego błędu, ale kod stop i nazwa sterownika nie zawsze wskazują prawdziwą przyczynę. Analizuj kilka zdarzeń, czas wystąpienia, zmianę sprzętu/sterowników, test RAM i stan dysku. Zachowaj oryginalne zrzuty przed czyszczeniem systemu. warning: Nie przesyłaj publicznie pełnych zrzutów pamięci — mogą zawierać dane użytkownika. Nie wyłączaj ochron systemowych na stałe. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record the stop code, failure time and workload at the moment of the crash.; Copy minidumps and event reports; remove personal data before sharing.; Review recent driver and hardware changes, but do not roll back multiple changes at once.; Run a memory test and inspect drive SMART; monitor temperatures.; Verify the hypothesis by repeating the scenario after one controlled change. bodyEn: A BSOD is the result of a critical failure, but the stop code and named driver do not always identify the root cause. Review multiple events, timing, hardware/driver changes, memory tests and drive health. Preserve original dumps before cleaning the system. warningEn: Do not publicly share full memory dumps; they may contain user data. Do not permanently disable system protections.','BSOD,minidump,stop code,driver','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-089','lesson','Windows i diagnostyka','Windows: analiza logów Podglądu zdarzeń i niezawodności','Windows: Event Viewer and Reliability Monitor analysis','steps: Zapisz datę i godzinę objawu oraz strefę czasową systemu.; Otwórz Monitor niezawodności i zanotuj zdarzenia krytyczne w tym przedziale.; W Podglądzie zdarzeń filtruj logi System i Application wokół czasu awarii.; Zapisz źródło, identyfikator zdarzenia i szczegóły, nie tylko poziom „Błąd”.; Porównaj co najmniej kilka powtórzeń i łącz wnioski z testami sprzętu. body: Podgląd zdarzeń i Monitor niezawodności pomagają zestawić awarie systemu z aktualizacjami, sterownikami i aplikacjami. Ostrzeżenie lub błąd nie zawsze oznacza przyczynę awarii. Ważna jest korelacja czasu i powtarzalność zdarzenia. warning: Logi mogą zawierać nazwy kont, ścieżki i identyfikatory. Zanonimizuj raport przed publikacją. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Record the symptom date/time and system time zone.; Open Reliability Monitor and note critical events in that window.; Filter System and Application logs around the failure in Event Viewer.; Record the source, event ID and details, not just the Error severity.; Compare multiple occurrences and correlate findings with hardware tests. bodyEn: Event Viewer and Reliability Monitor help correlate system failures with updates, drivers and applications. A warning or error is not automatically the cause. Timing correlation and repeatability matter. warningEn: Logs may contain account names, paths and identifiers. Redact reports before publishing.','Event Viewer,Reliability Monitor,logs','Opracowanie edukacyjne Akademii Serwisu PRO'),
('lesson:GLOBAL-090','lesson','Sterowniki','Sterowniki: identyfikacja sprzętu i bezpieczna instalacja','Drivers: hardware identification and safe installation','steps: Odczytaj identyfikator sprzętu i nazwę urządzenia w Menedżerze urządzeń.; Ustal dokładny model komputera/płyty oraz wersję Windows.; Pobierz pakiet z oficjalnej strony producenta i sprawdź podpis oraz obsługiwany system.; Utwórz punkt przywracania lub kopię sterownika, jeśli to możliwe.; Zainstaluj jeden pakiet, uruchom ponownie i sprawdź funkcję oraz logi urządzenia. body: Wybór sterownika powinien opierać się na identyfikatorze urządzenia, dokładnym modelu komputera, systemie operacyjnym i wersji sprzętu. Programy zbiorczo aktualizujące sterowniki mogą instalować niewłaściwe pakiety. Priorytetem są oficjalne pakiety producenta urządzenia lub komputera. warning: Nie instaluj sterowników z nieznanych agregatorów ani nie wyłączaj weryfikacji podpisów jako stałego rozwiązania. source: Opracowanie edukacyjne Akademii Serwisu PRO','stepsEn: Read the hardware ID and device name in Device Manager.; Identify the exact computer/motherboard model and Windows version.; Download the package from the official vendor site and check signature and OS support.; Create a restore point or driver backup where possible.; Install one package, reboot and verify device function and logs. bodyEn: Driver selection should be based on the hardware ID, exact computer model, operating system and hardware revision. Bulk driver-updater tools may install incorrect packages. Prefer official packages from the device or computer manufacturer. warningEn: Do not install drivers from unknown aggregators or permanently disable signature enforcement.','drivers,PCI ID,USB ID,INF,rollback','Opracowanie edukacyjne Akademii Serwisu PRO');
